class Solution {
  public long minOperations(int[] nums1, int[] nums2) {
    int n = nums1.length;
    long base = 0, extra = Long.MAX_VALUE;
    long t = nums2[n];
    for (int i = 0; i < n; i++) {
      long a = nums1[i], b = nums2[i];
      base += Math.abs(a - b);
      long lo = Math.min(a, b), hi = Math.max(a, b);
      long cost = t >= lo && t <= hi ? 0 : Math.min(Math.abs(a - t), Math.abs(b - t));
      extra = Math.min(extra, cost);
    }
    return base + 1 + extra;
  }
}
